package me.minis.ledger;
import android.content.*;import android.database.*;import android.net.Uri;import android.provider.DocumentsContract;import android.security.keystore.*;import android.util.Base64;import org.json.*;import javax.crypto.*;import javax.crypto.spec.*;import java.io.*;import java.security.*;import java.util.*;
/** User-authorized SAF directory. Only own generated encrypted versions are ever pruned. */
public final class BackupVault {
 private static final String ALIAS="qingji.backup.wrap.v1",PREFIX="QingJi-auto-";
 static synchronized String code(Context c)throws Exception{SharedPreferences p=LedgerDb.prefs(c);String blob=p.getString("backup_wrapped","");KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);SecretKey key;if(ks.containsAlias(ALIAS))key=(SecretKey)ks.getKey(ALIAS,null);else{if(!blob.isEmpty())throw new IOException("无法读取本机备份密钥，请使用之前保存的恢复码恢复");KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());key=g.generateKey();}
  Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");if(blob.isEmpty()){String code=BackupCrypto.newCode();cipher.init(Cipher.ENCRYPT_MODE,key);byte[] enc=cipher.doFinal(code.getBytes("UTF-8")),all=new byte[12+enc.length];System.arraycopy(cipher.getIV(),0,all,0,12);System.arraycopy(enc,0,all,12,enc.length);if(!p.edit().putString("backup_wrapped",Base64.encodeToString(all,Base64.NO_WRAP)).commit())throw new IOException("无法保存备份密钥");return code;}byte[] all=Base64.decode(blob,Base64.NO_WRAP);if(all.length<28)throw new IOException("本机备份密钥不完整");cipher.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,all,0,12));return new String(cipher.doFinal(all,12,all.length-12),"UTF-8");
 }
 static void export(Context c,LedgerDb db,OutputStream out)throws Exception{try(OutputStream encrypted=BackupHtml.encrypt(out,c.getAssets().open("backup-page.txt"),code(c))){db.exportBackup(encrypted);}}
 static JSONObject state(Context c)throws Exception{SharedPreferences p=LedgerDb.prefs(c);return new JSONObject().put("enabled",p.getBoolean("backup_auto",false)).put("directory",!p.getString("backup_tree","").isEmpty()).put("last",p.getLong("backup_last",0)).put("error",p.getString("backup_error","")).put("keep",p.getInt("backup_keep",7)).put("ack",p.getBoolean("backup_ack",false));}
 static void settings(Context c,JSONObject p)throws Exception{boolean enabled=p.getBoolean("enabled");int keep=p.optInt("keep",7);if(keep<2||keep>30)throw new IllegalArgumentException("历史版本保留2至30份");SharedPreferences pref=LedgerDb.prefs(c);if(enabled&&(!pref.getBoolean("backup_ack",false)||pref.getString("backup_tree","").isEmpty()))throw new IllegalStateException("请先保存恢复码并选择备份目录");pref.edit().putBoolean("backup_auto",enabled).putInt("backup_keep",keep).apply();}
 static String family(Context c)throws Exception{return BackupCrypto.hex(MessageDigest.getInstance("SHA-256").digest(BackupCrypto.key(code(c)))).substring(0,12);}
 static String name(Context c)throws Exception{return PREFIX+family(c)+"-"+new java.text.SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date())+"-"+UUID.randomUUID().toString().substring(0,8)+".html";}
 static Uri root(Uri tree){return DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));}
 static String digest(InputStream in)throws Exception{try(InputStream src=in){if(src==null)throw new IOException("无法读取备份校验");MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] b=new byte[32768];long count=0;int n;while((n=src.read(b))!=-1){if((count+=n)>(BackupStream.MAX_BYTES+1024*1024)*4/3+BackupHtml.MAX_TEMPLATE+256)throw new IOException("备份校验文件过大");md.update(b,0,n);}return BackupCrypto.hex(md.digest());}}
 static void copy(InputStream src,OutputStream out)throws IOException{if(src==null||out==null)throw new IOException("无法访问备份文件");byte[] b=new byte[32768];int n;while((n=src.read(b))!=-1)out.write(b,0,n);out.flush();}
 static synchronized void run(Context c,LedgerDb db,boolean force)throws Exception{SharedPreferences p=LedgerDb.prefs(c);if(!p.getBoolean("backup_auto",false)){if(force)throw new IllegalStateException("请先启用自动加密备份");return;}long now=System.currentTimeMillis(),last=p.getLong("backup_last",0);if(!force&&now>=last&&now-last<24*60*60*1000L)return;if(!p.getBoolean("backup_ack",false))throw new IllegalStateException("请先保存恢复码");File staged=File.createTempFile("qingji-export-",".qjb",c.getCacheDir());Uri created=null;boolean success=false;try{try(OutputStream out=new FileOutputStream(staged)){export(c,db,out);}String hash=digest(new FileInputStream(staged));Uri tree=Uri.parse(p.getString("backup_tree",""));created=DocumentsContract.createDocument(c.getContentResolver(),root(tree),"text/html",name(c));if(created==null)throw new IOException("无法创建备份文件");try(InputStream in=new FileInputStream(staged);OutputStream out=c.getContentResolver().openOutputStream(created,"wt")){copy(in,out);}if(!hash.equals(digest(c.getContentResolver().openInputStream(created))))throw new IOException("备份写入校验失败，旧版本保留");success=true;p.edit().putLong("backup_last",now).putString("backup_error","").commit();prune(c,tree,p.getInt("backup_keep",7),created);}catch(Exception e){p.edit().putString("backup_error",e instanceof SecurityException?"目录权限失效，请重新选择目录":success?"备份已保存，但历史版本清理未完成；请检查目录权限":"自动备份未完成，旧版本保留；请检查目录权限和空间").apply();throw e;}finally{staged.delete();if(!success&&created!=null)try{DocumentsContract.deleteDocument(c.getContentResolver(),created);}catch(Exception ignored){}}}
 static void prune(Context c,Uri tree,int keep,Uri newest)throws Exception{String ownPrefix=PREFIX+family(c)+"-";List<String[]> rows=new ArrayList<>();Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree));try(Cursor r=c.getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME},null,null,null)){if(r==null)throw new IOException("无法读取备份目录");while(r.moveToNext()){String n=r.getString(1);if(n!=null&&n.matches(java.util.regex.Pattern.quote(ownPrefix)+"[0-9]{8}-[0-9]{6}-[a-f0-9]{8}\\.(?:qjb|html)"))rows.add(new String[]{r.getString(0),n});}}String newestId=DocumentsContract.getDocumentId(newest);rows.removeIf(row->row[0].equals(newestId));rows.sort((a,b)->b[1].compareTo(a[1]));for(int i=keep-1;i<rows.size();i++){Uri uri=DocumentsContract.buildDocumentUriUsingTree(tree,rows.get(i)[0]);if(!DocumentsContract.deleteDocument(c.getContentResolver(),uri))throw new IOException("备份已保存，但旧版本清理失败");}}
 static void due(Context c,LedgerDb h){try{run(c,h,false);}catch(Exception ignored){}}
}
